static inchr parse_code(const char *s) {
    if (s[0] == '0' && (s[1] == 'x' || s[1] == 'X')) {
        return strtoul(s + 2, NULL, 16);
    }
    if (s[0] == '0' && s[1] != '\0' && isdigit(s[1])) {
        return strtoul(s + 1, NULL, 8);
    }
    return strtoul(s, NULL, 10);
}

static void load_control_file(const char *name) {
    FILE *f = open_control_file(name);
    if (!f) {
        fprintf(stderr, "%s: %s: Unable to open control file\n", progname, name);
        exit(1);
    }

    ControlFile *cf = (ControlFile*)calloc(1, sizeof(ControlFile));
    *last_cf_ptr = cf;
    last_cf_ptr = &(cf->next);

    Mapping **last_m = &(cf->mappings);

    char *line;
    while ((line = read_line(f)) != NULL) {
        char *p = line;
        while (isspace(*p)) p++;
        if (*p == '#' || *p == '\0') continue;
        if (strncmp(p, "flc2", 4) == 0) continue;

        if (*p == 'u' || *p == 'U') {
            cf->utf8_mode = 1;
            continue;
        }

        if (*p == 't' || *p == 'T') {
            p++;
            char src_str[256] = {0}, dst_str[256] = {0};
            if (sscanf(p, "%255s %255s", src_str, dst_str) == 2) {
                char *dash_src = strchr(src_str, '-');
                char *dash_dst = strchr(dst_str, '-');
                inchr s_start, s_end, d_start;
                if (dash_src) {
                    *dash_src = '\0';
                    s_start = (src_str[0] == '0' && (src_str[1] == 'x' || src_str[1] == 'X')) ? parse_code(src_str) : (unsigned char)src_str[0];
                    s_end = (dash_src[1] == '0' && (dash_src[2] == 'x' || dash_src[2] == 'X')) ? parse_code(dash_src + 1) : (unsigned char)dash_src[1];
                } else {
                    s_start = s_end = (src_str[0] == '0' && (src_str[1] == 'x' || src_str[1] == 'X')) ? parse_code(src_str) : (unsigned char)src_str[0];
                }
                if (dash_dst) {
                    *dash_dst = '\0';
                    d_start = (dst_str[0] == '0' && (dst_str[1] == 'x' || dst_str[1] == 'X')) ? parse_code(dst_str) : (unsigned char)dst_str[0];
                } else {
                    d_start = (dst_str[0] == '0' && (dst_str[1] == 'x' || dst_str[1] == 'X')) ? parse_code(dst_str) : (unsigned char)dst_str[0];
                }
                Mapping *m = (Mapping*)calloc(1, sizeof(Mapping));
                m->src_start = s_start;
                m->src_end = s_end;
                m->dst_start = d_start;
                *last_m = m;
                last_m = &(m->next);
            }
            continue;
        }

        // Direct mappings: 0x123 0x456 or 0x123-0x125 0x456
        char src_str[256] = {0}, dst_str[256] = {0};
        if (sscanf(p, "%255s %255s", src_str, dst_str) == 2) {
            char *dash_src = strchr(src_str, '-');
            inchr s_start, s_end, d_start;
            if (dash_src) {
                *dash_src = '\0';
                s_start = parse_code(src_str);
                s_end = parse_code(dash_src + 1);
            } else {
                s_start = s_end = parse_code(src_str);
            }
            d_start = parse_code(dst_str);
            Mapping *m = (Mapping*)calloc(1, sizeof(Mapping));
            m->src_start = s_start;
            m->src_end = s_end;
            m->dst_start = d_start;
            *last_m = m;
            last_m = &(m->next);
        }
    }
    fclose(f);
}

static char** read_figchar(FILE *f, char endchar, int *out_width) {
    char **table = (char**)malloc(sizeof(char*) * char_height);
    int max_w = 0;
    for (int r = 0; r < char_height; r++) {
        char *line = read_line(f);
        if (!line) {
            for (int i = 0; i < r; i++) free(table[i]);
            free(table);
            return NULL;
        }
        int len = strlen(line);
        // Strip trailing endchars
        while (len > 0 && line[len-1] == endchar) {
            line[len-1] = '\0';
            len--;
        }
        if (len > max_w) max_w = len;
        table[r] = strdup(line);
    }
    // Pad all rows to max_w with spaces if needed
    for (int r = 0; r < char_height; r++) {
        int len = strlen(table[r]);
        if (len < max_w) {
            char *new_row = (char*)malloc(max_w + 1);
            strcpy(new_row, table[r]);
            memset(new_row + len, ' ', max_w - len);
            new_row[max_w] = '\0';
            free(table[r]);
            table[r] = new_row;
        }
    }
    if (out_width) *out_width = max_w;
    return table;
}

static void load_font(const char *name) {
    FILE *f = open_font_file(name);
    if (!f) {
        fprintf(stderr, "%s: %s: Unable to open font file\n", progname, name);
        exit(1);
    }

    char *hdr = read_line(f);
    if (!hdr || (strncmp(hdr, "flf2", 4) != 0 && strncmp(hdr, "tlf2", 4) != 0)) {
        fprintf(stderr, "%s: %s: Not a FIGlet 2 font file\n", progname, name);
        exit(1);
    }

    hardblank = hdr[5];

    int params = sscanf(hdr + 6, "%d %d %d %d %d %d %d %d",
                        &char_height, &baseline, &maxlen, &oldlayout,
                        &codetag_count, &font_right2left, &full_layout, &codetag_count);

    // Header parameter order: height baseline maxlen oldlayout commentlines printdirection full_layout codetag_count
    int commentlines = 0;
    int params_read = sscanf(hdr + 6, "%d %d %d %d %d %d %d %d",
                             &char_height, &baseline, &maxlen, &oldlayout,
                             &commentlines, &font_right2left, &full_layout, &codetag_count);

    if (params_read < 5) {
        fprintf(stderr, "%s: %s: Not a FIGlet 2 font file\n", progname, name);
        exit(1);
    }

    // Skip comments
    for (int i = 0; i < commentlines; i++) {
        read_line(f);
    }

    // Read first character to determine endchar
    // Peek endchar from first line of space char
    long pos = ftell(f);
    char *first_line = read_line(f);
    if (!first_line) {
        fprintf(stderr, "%s: %s: Not a FIGlet 2 font file\n", progname, name);
        exit(1);
    }
    int len = strlen(first_line);
    char endchar = (len > 0) ? first_line[len-1] : '@';
    fseek(f, pos, SEEK_SET);

    // Read 95 standard ASCII chars (32..126)
    for (inchr ord = 32; ord <= 126; ord++) {
        int w = 0;
        char **tbl = read_figchar(f, endchar, &w);
        if (!tbl) break;
        add_char(ord, tbl, w);
    }

    // Read 7 Deutsch chars
    inchr deutsch_ords[7] = {196, 214, 220, 228, 246, 252, 223};
    for (int i = 0; i < 7; i++) {
        int w = 0;
        char **tbl = read_figchar(f, endchar, &w);
        if (!tbl) break;
        add_char(deutsch_ords[i], tbl, w);
    }

    // Read codetagged chars until EOF or codetag_count
    char *tagline;
    while ((tagline = read_line(f)) != NULL) {
        while (isspace(*tagline)) tagline++;
        if (*tagline == '\0') continue;
        inchr ord = parse_code(tagline);
        int w = 0;
        char **tbl = read_figchar(f, endchar, &w);
        if (!tbl) break;
        add_char(ord, tbl, w);
    }

    fclose(f);

    // Determine default_smush
    if (params_read >= 7 && full_layout > 0) {
        default_smush = full_layout;
    } else {
        if (oldlayout == -1) {
            default_smush = 0;
        } else if (oldlayout == 0) {
            default_smush = SM_KERN;
        } else {
            default_smush = SM_SMUSH;
            if (oldlayout & 1) default_smush |= SM_EQUAL;
            if (oldlayout & 2) default_smush |= SM_LOWLINE;
            if (oldlayout & 4) default_smush |= SM_HIERARCHY;
            if (oldlayout & 8) default_smush |= SM_PAIR;
            if (oldlayout & 16) default_smush |= SM_BIGX;
            if (oldlayout & 32) default_smush |= SM_HARDBLANK;
        }
    }
}

// Active smush calculation
static void setup_active_smush() {
    if (smushmode_cmd == -100000) {
        active_smush = default_smush;
    } else if (smushmode_cmd == 0) {
        active_smush = default_smush;
    } else if (smushmode_cmd == -1) {
        active_smush = 0; // full width
    } else if (smushmode_cmd == -2) {
        active_smush = SM_KERN;
    } else {
        if ((smushmode_cmd & SM_SMUSH) || (smushmode_cmd & SM_KERN)) {
            active_smush = smushmode_cmd;
        } else {
            active_smush = SM_SMUSH | smushmode_cmd;
        }
    }
}

// Smushing rules between subchar a and b
static char smush_chars(char a, char b) {
    if (a == ' ') return b;
    if (b == ' ') return a;

    if (!(active_smush & SM_SMUSH)) return '\0';

    if ((active_smush & 63) == 0) { // Universal smush
        if (b == hardblank) return a;
        return b;
    }

    // Rule 1: Equal
    if ((active_smush & SM_EQUAL) && a == b) {
        if (a != hardblank || (active_smush & SM_HARDBLANK)) return a;
    }

    // Rule 2: Lowline
    if (active_smush & SM_LOWLINE) {
        if (a == '_' && strchr("|/\\[]{}()<>", b)) return b;
        if (b == '_' && strchr("|/\\[]{}()<>", a)) return a;
    }

    // Rule 3: Hierarchy
    if (active_smush & SM_HIERARCHY) {
        int rank_a = 0, rank_b = 0;
        if (a == '|') rank_a = 1;
        else if (a == '/' || a == '\\') rank_a = 2;
        else if (a == '[' || a == ']') rank_a = 3;
        else if (a == '{' || a == '}') rank_a = 4;
        else if (a == '(' || a == ')') rank_a = 5;
        else if (a == '<' || a == '>') rank_a = 6;

        if (b == '|') rank_b = 1;
        else if (b == '/' || b == '\\') rank_b = 2;
        else if (b == '[' || b == ']') rank_b = 3;
        else if (b == '{' || b == '}') rank_b = 4;
        else if (b == '(' || b == ')') rank_b = 5;
        else if (b == '<' || b == '>') rank_b = 6;

        if (rank_a > 0 && rank_b > 0) {
            if (rank_a > rank_b) return a;
            if (rank_b > rank_a) return b;
        }
    }

    // Rule 4: Pair
    if (active_smush & SM_PAIR) {
        if ((a == '[' && b == ']') || (a == ']' && b == '[')) return '|';
        if ((a == '{' && b == '}') || (a == '}' && b == '{')) return '|';
        if ((a == '(' && b == ')') || (a == ')' && b == '(')) return '|';
    }

    // Rule 5: BigX
    if (active_smush & SM_BIGX) {
        if (a == '/' && b == '\\') return '|';
        if (a == '\\' && b == '/') return 'Y';
        if (a == '>' && b == '<') return 'X';
    }

    // Rule 6: Hardblank
    if ((active_smush & SM_HARDBLANK) && a == hardblank && b == hardblank) {
        return hardblank;
    }

    return '\0';
}

// Line Accumulator structure
typedef struct {
    char **output; // char_height rows, dynamically allocated string per row
    int width;
    int char_count;
    int is_space_at[1024]; // positions where spaces/words break
} LineBuffer;

static LineBuffer* create_line_buffer() {
    LineBuffer *buf = (LineBuffer*)calloc(1, sizeof(LineBuffer));
    buf->output = (char**)malloc(sizeof(char*) * char_height);
    for (int r = 0; r < char_height; r++) {
        buf->output[r] = (char*)calloc(1, 1); // empty string
    }
    buf->width = 0;
    return buf;
}

static void free_line_buffer(LineBuffer *buf) {
    if (!buf) return;
    for (int r = 0; r < char_height; r++) free(buf->output[r]);
    free(buf->output);
    free(buf);
}

// Calculate overlap / shift amount when adding character B to line A
static int calc_overlap(LineBuffer *line, char **B_table, int B_width) {
    if (line->width == 0) return 0;
    if (active_smush == 0) return 0; // full width

    int min_kern = 100000;
    for (int r = 0; r < char_height; r++) {
        char *rowA = line->output[r];
        int lenA = strlen(rowA);
        char *rowB = B_table[r];

        int trailingA = 0;
        for (int i = lenA - 1; i >= 0; i--) {
            if (rowA[i] == ' ') trailingA++;
            else break;
        }

        int leadingB = 0;
        for (int i = 0; i < B_width; i++) {
            if (rowB[i] == ' ') leadingB++;
            else break;
        }

        int kern_row = trailingA + leadingB;
        if (kern_row < min_kern) min_kern = kern_row;
    }

    if (min_kern == 100000) min_kern = 0;

    // Check if 1-column smushing is possible
    if (!(active_smush & SM_SMUSH)) {
        return min_kern; // Kerning only
    }

    int smush_ok = 1;
    for (int r = 0; r < char_height; r++) {
        char *rowA = line->output[r];
        int lenA = strlen(rowA);
        char *rowB = B_table[r];

        int trailingA = 0;
        for (int i = lenA - 1; i >= 0; i--) {
            if (rowA[i] == ' ') trailingA++;
            else break;
        }

        int leadingB = 0;
        for (int i = 0; i < B_width; i++) {
            if (rowB[i] == ' ') leadingB++;
            else break;
        }

        if (trailingA + leadingB == min_kern) {
            int posA = lenA - 1 - trailingA;
            int posB = leadingB;
            char charA = (posA >= 0) ? rowA[posA] : ' ';
            char charB = (posB < B_width) ? rowB[posB] : ' ';

            if (charA != ' ' && charB != ' ') {
                if (smush_chars(charA, charB) == '\0') {
                    smush_ok = 0;
                    break;
                }
            }
        }
    }

    if (smush_ok) {
        return min_kern + 1;
    }
    return min_kern;
}

// Append character B to line buffer with shift
static void append_char_to_line(LineBuffer *line, char **B_table, int B_width, int shift) {
    int old_width = line->width;
    int new_width = old_width + B_width - shift;
    if (new_width < old_width) new_width = old_width;

    for (int r = 0; r < char_height; r++) {
        char *rowA = line->output[r];
        int lenA = strlen(rowA);
        char *rowB = B_table[r];

        char *new_row = (char*)malloc(new_width + 1);
        memset(new_row, ' ', new_width);
        new_row[new_width] = '\0';

        // Copy rowA
        memcpy(new_row, rowA, lenA);

        // Merge rowB at offset (old_width - shift)
        int offset = old_width - shift;
        for (int i = 0; i < B_width; i++) {
            int pos = offset + i;
            if (pos < 0) continue;
            char b_ch = rowB[i];
            if (pos < lenA) {
                char a_ch = new_row[pos];
                if (a_ch == ' ') {
                    new_row[pos] = b_ch;
                } else if (b_ch != ' ') {
                    char sm = smush_chars(a_ch, b_ch);
                    new_row[pos] = (sm != '\0') ? sm : b_ch;
                }
            } else {
                new_row[pos] = b_ch;
            }
        }

        free(line->output[r]);
        line->output[r] = new_row;
    }

    line->width = new_width;
    line->char_count++;
}

// Flush/print line buffer
static void print_line(LineBuffer *line) {
    if (line->width == 0) return;

    int eff_just = justification;
    if (eff_just == -1) {
        eff_just = right2left ? 1 : 0;
    }

    int total_width = line->width;
    int pad = 0;
    if (eff_just == 1) { // Right
        pad = outwidth - total_width;
        if (pad < 0) pad = 0;
    } else if (eff_just == 2) { // Center
        pad = (outwidth - total_width) / 2;
        if (pad < 0) pad = 0;
    }

    for (int r = 0; r < char_height; r++) {
        char *row = line->output[r];
        int len = strlen(row);

        // Strip trailing spaces
        while (len > 0 && row[len-1] == ' ') {
            row[len-1] = '\0';
            len--;
        }

        if (len > 0) {
            for (int k = 0; k < pad; k++) putchar(' ');
            for (int k = 0; k < len; k++) {
                char c = row[k];
                putchar(c == hardblank ? ' ' : c);
            }
        }
        putchar('\n');
    }
}

// UTF-8 decoder helper
static inchr decode_utf8(const unsigned char **p) {
    unsigned char c = **p;
    if (c < 0x80) {
        (*p)++;
        return c;
    }
    if ((c & 0xE0) == 0xC0) {
        inchr res = (c & 0x1F) << 6;
        (*p)++;
        if (**p) res |= (**p & 0x3F), (*p)++;
        return res;
    }
    if ((c & 0xF0) == 0xE0) {
        inchr res = (c & 0x0F) << 12;
        (*p)++;
        if (**p) res |= (**p & 0x3F), (*p)++;
        if (**p) res |= (**p & 0x3F), (*p)++;
        return res;
    }
    if ((c & 0xF8) == 0xF0) {
        inchr res = (c & 0x07) << 18;
        (*p)++;
        if (**p) res |= (**p & 0x3F), (*p)++;
        if (**p) res |= (**p & 0x3F), (*p)++;
        if (**p) res |= (**p & 0x3F), (*p)++;
        return res;
    }
    (*p)++;
    return c;
}

// Process string or stream input
static void process_text(const char *text) {
    LineBuffer *curr_line = create_line_buffer();

    int is_utf8 = 0;
    ControlFile *cf = control_files;
    while (cf) {
        if (cf->utf8_mode) is_utf8 = 1;
        cf = cf->next;
    }

    const unsigned char *p = (const unsigned char*)text;
    while (*p) {
        inchr c;
        if (is_utf8) {
            c = decode_utf8(&p);
        } else {
            c = *p;
            p++;
        }

        if (c == '\r') continue;
        if (c == '\n') {
            print_line(curr_line);
            free_line_buffer(curr_line);
            curr_line = create_line_buffer();
            continue;
        }

        c = map_char(c);

        CharNode *node = get_char_node(c);
        if (!node) {
            node = get_char_node(' ');
        }
        if (!node) continue;

        int shift = calc_overlap(curr_line, node->table, node->width);

        if (outwidth > 1 && curr_line->width > 0 && (curr_line->width + node->width - shift) > outwidth) {
            // Need line wrap!
