                    }
                    strcat(para_buf, tp);
                    para_len += strlen(tp);
                }
            }
            if (para_len > 0) {
                strcat(para_buf, "\n");
                process_text(para_buf);
            }
            free(para_buf);
        } else {
            while (fgets(line_buf, sizeof(line_buf), stdin)) {
                process_text(line_buf);
            }
        }
    }

    return 0;
}
