        free(buf);
    } else {
        char line_buf[8192];
        if (paragraphmode) {
            char *para_buf = (char*)malloc(65536);
            para_buf[0] = '\0';
            size_t para_len = 0;

            while (fgets(line_buf, sizeof(line_buf), stdin)) {
                size_t l = strlen(line_buf);
                while (l > 0 && (line_buf[l-1] == '\r' || line_buf[l-1] == '\n')) {
                    line_buf[l-1] = '\0';
                    l--;
                }

                char *tp = line_buf;
                while (isspace(*tp)) tp++;
                if (*tp == '\0') {
                    if (para_len > 0) {
                        strcat(para_buf, "\n");
                        process_text(para_buf);
                        para_buf[0] = '\0';
                        para_len = 0;
                    }
                    process_text("\n");
                } else {
                    if (para_len > 0) {
                        strcat(para_buf, " ");
                        para_len++;
                    }
                    strcat(para_buf, tp);
                    para_len += strlen(tp);
                }
            }
            if (para_len > 0) {
                strcat(para_buf, "\n");
                process_text(para_buf);
            }
            free(para_buf);
        } else {
            while (fgets(line_buf, sizeof(line_buf), stdin)) {
                process_text(line_buf);
            }
        }
    }

    return 0;
}
