        if (a == '/' && b == '\\') return '|';
        if (a == '\\' && b == '/') return 'Y';
        if (a == '>' && b == '<') return 'X';
    }

    if ((active_smush & SM_HARDBLANK) && a == hardblank && b == hardblank) {
        return hardblank;
    }

    return '\0';
}

