                    print_line(line);
                    free_line_buffer(line);
                    line = NULL;
                    idx = last_space_q_idx + 1;
                    break;
                } else {
                    print_line(line);
                    free_line_buffer(line);
                    line = NULL;
                    idx = i;
                    break;
                }
            }

