    for (int r = 0; r < char_height; r++) {
        char *line = read_line(f);
        if (!line) {
            for (int i = 0; i < r; i++) free(table[i]);
            free(table);
            return NULL;
        }
        int len = strlen(line);
        if (r == 0 && len > 0) {
            char_endchar = line[len - 1];
        }
        while (len > 0 && line[len-1] == char_endchar) {
            line[len-1] = '\0';
            len--;
        }
        int ulen = utf8_strlen(line);
        if (ulen > max_w) max_w = ulen;
        table[r] = strdup(line);
    }
    for (int r = 0; r < char_height; r++) {
        int ulen = utf8_strlen(table[r]);
        if (ulen < max_w) {
            int need = max_w - ulen;
            int blen = strlen(table[r]);
            char *new_row = (char*)malloc(blen + need + 1);
            strcpy(new_row, table[r]);
            memset(new_row + blen, ' ', need);
