}

static void free_line_buffer(LineBuffer *buf) {
    if (!buf) return;
    for (int r = 0; r < char_height; r++) free(buf->output[r]);
    free(buf->output);
    free(buf);
}

static int calc_overlap_ltr(LineBuffer *line, char **B_table, int B_width) {
    if (outwidth == 1) return 0;
    if (line->width == 0) {
        if (active_smush == 0) return 0;
        int min_leading = 100000;
        for (int r = 0; r < char_height; r++) {
            int leading = 0;
            for (int i = 0; i < B_width; i++) {
                if (B_table[r][i] == ' ') leading++;
                else break;
            }
            if (leading < min_leading) min_leading = leading;
        }
        if (min_leading == 100000) min_leading = 0;
        return min_leading;
    }

    if (active_smush == 0) return 0;

    int min_kern = 100000;
    for (int r = 0; r < char_height; r++) {
        char *rowA = line->output[r];
        int lenA = utf8_strlen(rowA);
        char *rowB = B_table[r];

        int trailingA = 0;
        for (int i = lenA - 1; i >= 0; i--) {
            if (rowA[i] == ' ') trailingA++;
            else break;
        }

        int leadingB = 0;
        for (int i = 0; i < B_width; i++) {
            if (rowB[i] == ' ') leadingB++;
            else break;
        }

        int kern_row = trailingA + leadingB;
        if (kern_row < min_kern) min_kern = kern_row;
    }

    if (min_kern == 100000) min_kern = 0;

    if (!(active_smush & SM_SMUSH)) {
        return min_kern;
    }

    int smush_ok = 1;
    for (int r = 0; r < char_height; r++) {
        char *rowA = line->output[r];
        int lenA = utf8_strlen(rowA);
        char *rowB = B_table[r];

        int trailingA = 0;
        for (int i = lenA - 1; i >= 0; i--) {
            if (rowA[i] == ' ') trailingA++;
            else break;
        }

        int leadingB = 0;
        for (int i = 0; i < B_width; i++) {
            if (rowB[i] == ' ') leadingB++;
            else break;
        }

        if (trailingA + leadingB == min_kern) {
            int posA = lenA - 1 - trailingA;
            int posB = leadingB;
            char charA = (posA >= 0) ? rowA[posA] : ' ';
            char charB = (posB < B_width) ? rowB[posB] : ' ';

            if (charA != ' ' && charB != ' ') {
                if (smush_chars(charA, charB) == '\0') {
                    smush_ok = 0;
                    break;
                }
            }
        }
    }

    if (smush_ok) {
        return min_kern + 1;
    }
    return min_kern;
}

