#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <unistd.h>
#include <getopt.h>
#include <sys/ioctl.h>

#define DEFAULTFONTDIR "/usr/local/share/figlet"
#define DEFAULTFONTFILE "standard"

#define SM_EQUAL 1
#define SM_LOWLINE 2
#define SM_HIERARCHY 4
#define SM_PAIR 8
#define SM_BIGX 16
#define SM_HARDBLANK 32
#define SM_KERN 64
#define SM_SMUSH 128
#define SM_SMUSHVERT 256
#define SM_KERNVERT 512

typedef unsigned long inchr;

typedef struct CharNode {
    inchr ord;
    char **table; // char_height rows
    int width;
    struct CharNode *next;
} CharNode;

typedef struct Mapping {
    inchr src_start;
    inchr src_end;
    inchr dst_start;
    struct Mapping *next;
} Mapping;

typedef struct ControlFile {
    Mapping *mappings;
    int utf8_mode;
    struct ControlFile *next;
} ControlFile;

static char *progname = "executable";
static char *fontdir = NULL;
static char *fontname = NULL;
static int outwidth = 80;
static int justification = -1; // -1: default, 0: left, 1: right, 2: center
static int right2left = 0;
static int paragraphmode = 0;
static int deutschmode = 0;
static int smushmode_cmd = -100000;
static int infocode = -1;
static int use_terminal_width = 0;

static ControlFile *control_files = NULL;
static ControlFile **last_cf_ptr = &control_files;

// Font parameters
static char hardblank = '$';
static int char_height = 0;
static int baseline = 0;
static int maxlen = 0;
static int oldlayout = 0;
static int font_right2left = 0;
static int full_layout = 0;
static int codetag_count = 0;
static int default_smush = 0;
static int active_smush = 0;

#define HASH_SIZE 1024
static CharNode *char_hash[HASH_SIZE];

static int utf8_strlen(const char *s) {
    int count = 0;
    const unsigned char *p = (const unsigned char*)s;
    while (*p) {
        if ((*p & 0xC0) != 0x80) count++;
        p++;
    }
    return count;
}

static int utf8_byte_offset(const char *s, int col_count) {
    const unsigned char *p = (const unsigned char*)s;
    for (int i = 0; i < col_count && *p; i++) {
        if ((*p & 0x80) == 0) p += 1;
        else if ((*p & 0xE0) == 0xC0) p += 2;
        else if ((*p & 0xF0) == 0xE0) p += 3;
        else if ((*p & 0xF8) == 0xF0) p += 4;
        else p += 1;
    }
    return (int)(p - (const unsigned char*)s);
}

static void add_char(inchr ord, char **table, int width) {
    unsigned int h = (unsigned int)(ord % HASH_SIZE);
    CharNode *node = (CharNode*)malloc(sizeof(CharNode));
    node->ord = ord;
    node->table = table;
    node->width = width;
    node->next = char_hash[h];
    char_hash[h] = node;
}

static CharNode* get_char_node(inchr ord) {
    unsigned int h = (unsigned int)(ord % HASH_SIZE);
    CharNode *curr = char_hash[h];
    while (curr) {
        if (curr->ord == ord) return curr;
        curr = curr->next;
    }
    return NULL;
}

static char *get_basename(char *path) {
    char *p = strrchr(path, '/');
    return p ? p + 1 : path;
}

static void print_usage(FILE *stream) {
    fprintf(stream, "Usage: %s [ -cklnoprstvxDELNRSWX ] [ -d fontdirectory ]\n", progname);
    fprintf(stream, "              [ -f fontfile ] [ -m smushmode ] [ -w outputwidth ]\n");
    fprintf(stream, "              [ -C controlfile ] [ -I infocode ] [ message ]\n");
}

static void print_version() {
    printf("FIGlet Copyright (C) 1991-2012 Glenn Chappell, Ian Chai, John Cowan,\n");
    printf("Christiaan Keet and Claudio Matsuoka\n");
    printf("Internet: <info@figlet.org> Version: 2.2.5, date: 31 May 2012\n\n");
    printf("FIGlet, along with the various FIGlet fonts and documentation, may be\n");
    printf("freely copied and distributed.\n\n");
    printf("If you use FIGlet, please send an e-mail message to <info@figlet.org>.\n\n");
