        struct winsize ws;
        if (ioctl(STDOUT_FILENO, TIOCGWINSZ, &ws) == 0 && ws.ws_col > 0) {
            outwidth = ws.ws_col;
        } else if (ioctl(STDERR_FILENO, TIOCGWINSZ, &ws) == 0 && ws.ws_col > 0) {
            outwidth = ws.ws_col;
        } else if (ioctl(STDIN_FILENO, TIOCGWINSZ, &ws) == 0 && ws.ws_col > 0) {
            outwidth = ws.ws_col;
        }
    }

    if (infocode >= 0) {
        switch (infocode) {
            case 0:
                print_version();
                return 0;
            case 1:
                printf("20205\n");
                return 0;
            case 2:
