                        process_text("\n");
                        para_buf[0] = '\0';
                        para_len = 0;
                    }
                    process_text("\n");
                } else {
                    if (para_len > 0) {
                        strcat(para_buf, " ");
                        para_len++;
                    }
                    strcat(para_buf, tp);
                    para_len += strlen(tp);
                }
            }
            if (para_len > 0) {
                process_text(para_buf);
            }
            free(para_buf);
        } else {
            while (fgets(line_buf, sizeof(line_buf), stdin)) {
                size_t l = strlen(line_buf);
                if (l > 0 && line_buf[l-1] == '\n') {
                    process_text(line_buf);
                } else {
                    char tmp[8193];
                    snprintf(tmp, sizeof(tmp), "%s\n", line_buf);
                    process_text(tmp);
                }
            }
        }
    }

    return 0;
}
