    if (deutschmode && control_files == NULL) {
        if (c == '[') c = 196;
        else if (c == '\\') c = 214;
        else if (c == ']') c = 220;
        else if (c == '{') c = 228;
        else if (c == '|') c = 246;
        else if (c == '}') c = 252;
        else if (c == '~') c = 223;
