    if (!fgets(buf, sizeof(buf), f)) return NULL;
    size_t len = strlen(buf);
    while (len > 0 && (buf[len-1] == '\n' || buf[len-1] == '\r')) {
        buf[len-1] = '\0';
        len--;
    }
    return buf;
}

static int open_file_try(const char *path, FILE **f) {
    *f = fopen(path, "r");
    return (*f != NULL);
}

static FILE* open_font_file(const char *name) {
    FILE *f = NULL;
    char path[2048];
    int has_slash = (strchr(name, '/') != NULL);
    int has_ext = (strlen(name) > 4 && (strcmp(name + strlen(name) - 4, ".flf") == 0 || strcmp(name + strlen(name) - 4, ".tlf") == 0));

    if (has_slash) {
        if (open_file_try(name, &f)) return f;
        if (!has_ext) {
            snprintf(path, sizeof(path), "%s.flf", name);
            if (open_file_try(path, &f)) return f;
            snprintf(path, sizeof(path), "%s.tlf", name);
            if (open_file_try(path, &f)) return f;
        }
        return NULL;
    }

    const char *dir = fontdir ? fontdir : (getenv("FIGLET_FONTDIR") ? getenv("FIGLET_FONTDIR") : DEFAULTFONTDIR);

    if (has_ext) {
        snprintf(path, sizeof(path), "%s/%s", dir, name);
        if (open_file_try(path, &f)) return f;
        snprintf(path, sizeof(path), "./%s", name);
        if (open_file_try(path, &f)) return f;
    } else {
        snprintf(path, sizeof(path), "%s/%s.flf", dir, name);
        if (open_file_try(path, &f)) return f;
        snprintf(path, sizeof(path), "%s/%s.tlf", dir, name);
        if (open_file_try(path, &f)) return f;
        snprintf(path, sizeof(path), "./%s.flf", name);
        if (open_file_try(path, &f)) return f;
        snprintf(path, sizeof(path), "./%s.tlf", name);
        if (open_file_try(path, &f)) return f;
        snprintf(path, sizeof(path), "%s/%s", dir, name);
        if (open_file_try(path, &f)) return f;
        snprintf(path, sizeof(path), "./%s", name);
        if (open_file_try(path, &f)) return f;
    }
    return NULL;
}

