            int blen = strlen(rowB);
            for (int i = 0; i < blen; i++) {
                char b_ch = rowB[i];
                int pos = i;
                if (pos < new_width) {
                    char a_ch = new_row[pos];
                    if (a_ch == ' ') {
                        new_row[pos] = b_ch;
                    } else if (b_ch != ' ') {
