                    s_start = s_end = (src_str[0] == '0' && (src_str[1] == 'x' || src_str[1] == 'X')) ? parse_code(src_str) : (unsigned char)src_str[0];
                }
                if (dash_dst) {
                    *dash_dst = '\0';
                    d_start = (dst_str[0] == '0' && (dst_str[1] == 'x' || dst_str[1] == 'X')) ? parse_code(dash_dst) : (unsigned char)dash_dst[0];
