static void add_char(inchr ord, char **table, int width) {
    unsigned int h = (unsigned int)(ord % HASH_SIZE);
    CharNode *node = (CharNode*)malloc(sizeof(CharNode));
    node->ord = ord;
    node->table = table;
    node->width = width;
    node->next = char_hash[h];
    char_hash[h] = node;
}

static CharNode* get_char_node(inchr ord) {
    unsigned int h = (unsigned int)(ord % HASH_SIZE);
    CharNode *curr = char_hash[h];
    while (curr) {
        if (curr->ord == ord) return curr;
        curr = curr->next;
    }
    return NULL;
}

