                printf("%s\n", fontname ? fontname : DEFAULTFONTFILE);
                return 0;
            case 4:
                printf("%d\n", outwidth);
                return 0;
            case 5:
                printf("flf2 tlf2\n");
                return 0;
            default:
                return 0;
        }
    }

    load_font(fontname ? fontname : DEFAULTFONTFILE);
    setup_active_smush();

    if (optind < argc) {
        size_t total_len = 0;
        for (int i = optind; i < argc; i++) {
            total_len += strlen(argv[i]) + 1;
        }
        char *buf = (char*)malloc(total_len + 1);
        buf[0] = '\0';
        for (int i = optind; i < argc; i++) {
            strcat(buf, argv[i]);
            if (i < argc - 1) strcat(buf, " ");
        }
        process_text(buf);
        free(buf);
    } else {
        char line_buf[8192];
        if (paragraphmode) {
            char *para_buf = (char*)malloc(65536);
