        } else {
            while (fgets(line_buf, sizeof(line_buf), stdin)) {
                size_t l = strlen(line_buf);
                if (l > 0 && line_buf[l-1] == '\n') {
                    process_text(line_buf);
                } else {
                    char tmp[8193];
                    snprintf(tmp, sizeof(tmp), "%s\n", line_buf);
                    process_text(tmp);
                }
            }
        }
    }

    return 0;
}
