    printf("FIGlet, along with the various FIGlet fonts and documentation, may be\n");
    printf("freely copied and distributed.\n\n");
    printf("If you use FIGlet, please send an e-mail message to <info@figlet.org>.\n\n");
    printf("The latest version of FIGlet is available from the web site,\n");
    printf("\thttp://www.figlet.org/\n\n");
    print_usage(stdout);
}

static inchr map_char(inchr c) {
    ControlFile *cf = control_files;
    while (cf) {
        Mapping *m = cf->mappings;
        while (m) {
            if (c >= m->src_start && c <= m->src_end) {
                c = m->dst_start + (c - m->src_start);
                break;
            }
            m = m->next;
        }
        cf = cf->next;
    }
    if (deutschmode && control_files == NULL) {
        if (c == '[') c = 196;
        else if (c == '\\') c = 214;
        else if (c == ']') c = 220;
        else if (c == '{') c = 228;
        else if (c == '|') c = 246;
        else if (c == '}') c = 252;
        else if (c == '~') c = 223;
    }
    return c;
}

static char* read_line(FILE *f) {
    static char buf[4096];
    if (!fgets(buf, sizeof(buf), f)) return NULL;
    size_t len = strlen(buf);
    while (len > 0 && (buf[len-1] == '\n' || buf[len-1] == '\r')) {
        buf[len-1] = '\0';
        len--;
    }
    return buf;
}

static int open_file_try(const char *path, FILE **f) {
    *f = fopen(path, "r");
    return (*f != NULL);
}

static FILE* open_font_file(const char *name) {
    FILE *f = NULL;
    char path[2048];
    int has_slash = (strchr(name, '/') != NULL);
    int has_ext = (strlen(name) > 4 && (strcmp(name + strlen(name) - 4, ".flf") == 0 || strcmp(name + strlen(name) - 4, ".tlf") == 0));

    if (has_slash) {
        if (open_file_try(name, &f)) return f;
        if (!has_ext) {
            snprintf(path, sizeof(path), "%s.flf", name);
            if (open_file_try(path, &f)) return f;
            snprintf(path, sizeof(path), "%s.tlf", name);
            if (open_file_try(path, &f)) return f;
        }
        return NULL;
    }

    const char *dir = fontdir ? fontdir : (getenv("FIGLET_FONTDIR") ? getenv("FIGLET_FONTDIR") : DEFAULTFONTDIR);

    if (has_ext) {
        snprintf(path, sizeof(path), "%s/%s", dir, name);
        if (open_file_try(path, &f)) return f;
        snprintf(path, sizeof(path), "./%s", name);
        if (open_file_try(path, &f)) return f;
    } else {
        snprintf(path, sizeof(path), "%s/%s.flf", dir, name);
        if (open_file_try(path, &f)) return f;
        snprintf(path, sizeof(path), "%s/%s.tlf", dir, name);
        if (open_file_try(path, &f)) return f;
        snprintf(path, sizeof(path), "./%s.flf", name);
        if (open_file_try(path, &f)) return f;
        snprintf(path, sizeof(path), "./%s.tlf", name);
        if (open_file_try(path, &f)) return f;
        snprintf(path, sizeof(path), "%s/%s", dir, name);
        if (open_file_try(path, &f)) return f;
        snprintf(path, sizeof(path), "./%s", name);
        if (open_file_try(path, &f)) return f;
    }
    return NULL;
}

static FILE* open_control_file(const char *name) {
    FILE *f = NULL;
    char path[2048];
    int has_slash = (strchr(name, '/') != NULL);
    int has_ext = (strlen(name) > 4 && strcmp(name + strlen(name) - 4, ".flc") == 0);

    if (has_slash) {
        if (open_file_try(name, &f)) return f;
        if (!has_ext) {
            snprintf(path, sizeof(path), "%s.flc", name);
            if (open_file_try(path, &f)) return f;
        }
        return NULL;
    }

    const char *dir = fontdir ? fontdir : (getenv("FIGLET_FONTDIR") ? getenv("FIGLET_FONTDIR") : DEFAULTFONTDIR);

    if (has_ext) {
        snprintf(path, sizeof(path), "%s/%s", dir, name);
        if (open_file_try(path, &f)) return f;
        snprintf(path, sizeof(path), "./%s", name);
        if (open_file_try(path, &f)) return f;
    } else {
        snprintf(path, sizeof(path), "%s/%s.flc", dir, name);
        if (open_file_try(path, &f)) return f;
        snprintf(path, sizeof(path), "./%s.flc", name);
        if (open_file_try(path, &f)) return f;
        snprintf(path, sizeof(path), "%s/%s", dir, name);
        if (open_file_try(path, &f)) return f;
        snprintf(path, sizeof(path), "./%s", name);
        if (open_file_try(path, &f)) return f;
    }
    return NULL;
}

static inchr parse_code(const char *s) {
    if (s[0] == '\\') s++;
    if (s[0] == '0' && (s[1] == 'x' || s[1] == 'X')) {
        return strtoul(s + 2, NULL, 16);
    }
    if (s[0] == '0' && s[1] != '\0' && isdigit(s[1])) {
        return strtoul(s + 1, NULL, 8);
    }
    return strtoul(s, NULL, 10);
}

static void load_control_file(const char *name) {
    FILE *f = open_control_file(name);
    if (!f) {
        fprintf(stderr, "%s: %s: Unable to open control file\n", progname, name);
        exit(1);
    }

    ControlFile *cf = (ControlFile*)calloc(1, sizeof(ControlFile));
    *last_cf_ptr = cf;
    last_cf_ptr = &(cf->next);

    Mapping **last_m = &(cf->mappings);

    char *line;
    while ((line = read_line(f)) != NULL) {
        char *p = line;
        while (isspace(*p)) p++;
        if (*p == '#' || *p == '\0') continue;
        if (strncmp(p, "flc2", 4) == 0) continue;

        if (*p == 'u' || *p == 'U') {
            cf->utf8_mode = 1;
            continue;
        }

        if (*p == 't' || *p == 'T') {
            p++;
            char src_str[256] = {0}, dst_str[256] = {0};
            if (sscanf(p, "%255s %255s", src_str, dst_str) == 2) {
                char *s_p = src_str[0] == '\\' ? src_str + 1 : src_str;
                char *d_p = dst_str[0] == '\\' ? dst_str + 1 : dst_str;
                char *dash_src = strchr(s_p, '-');
                char *dash_dst = strchr(d_p, '-');
                inchr s_start, s_end, d_start;
                if (dash_src) {
                    *dash_src = '\0';
                    s_start = (s_p[0] == '0' && (s_p[1] == 'x' || s_p[1] == 'X')) ? parse_code(s_p) : (unsigned char)s_p[0];
                    s_end = (dash_src[1] == '0' && (dash_src[2] == 'x' || dash_src[2] == 'X')) ? parse_code(dash_src + 1) : (unsigned char)dash_src[1];
                } else {
                    s_start = s_end = (s_p[0] == '0' && (s_p[1] == 'x' || s_p[1] == 'X')) ? parse_code(s_p) : (unsigned char)s_p[0];
                }
                if (dash_dst) {
                    *dash_dst = '\0';
                    d_start = (d_p[0] == '0' && (d_p[1] == 'x' || d_p[1] == 'X')) ? parse_code(d_p) : (unsigned char)d_p[0];
                } else {
                    d_start = (d_p[0] == '0' && (d_p[1] == 'x' || d_p[1] == 'X')) ? parse_code(d_p) : (unsigned char)d_p[0];
                }
                Mapping *m = (Mapping*)calloc(1, sizeof(Mapping));
                m->src_start = s_start;
                m->src_end = s_end;
                m->dst_start = d_start;
                *last_m = m;
                last_m = &(m->next);
            }
            continue;
        }

        char src_str[256] = {0}, dst_str[256] = {0};
        if (sscanf(p, "%255s %255s", src_str, dst_str) == 2) {
            char *s_p = src_str[0] == '\\' ? src_str + 1 : src_str;
            char *d_p = dst_str[0] == '\\' ? dst_str + 1 : dst_str;
            char *dash_src = strchr(s_p, '-');
            inchr s_start, s_end, d_start;
            if (dash_src) {
                *dash_src = '\0';
                s_start = parse_code(s_p);
                s_end = parse_code(dash_src + 1);
            } else {
                s_start = s_end = parse_code(s_p);
            }
            d_start = parse_code(d_p);
            Mapping *m = (Mapping*)calloc(1, sizeof(Mapping));
            m->src_start = s_start;
            m->src_end = s_end;
            m->dst_start = d_start;
            *last_m = m;
            last_m = &(m->next);
        }
    }
    fclose(f);
}

static char** read_figchar(FILE *f, int *out_width) {
    char **table = (char**)malloc(sizeof(char*) * char_height);
    int max_w = 0;
    char char_endchar = '@';

    for (int r = 0; r < char_height; r++) {
        char *line = read_line(f);
        if (!line) {
            for (int i = 0; i < r; i++) free(table[i]);
            free(table);
            return NULL;
        }
        int len = strlen(line);
        if (r == 0 && len > 0) {
            char_endchar = line[len - 1];
        }
        while (len > 0 && line[len-1] == char_endchar) {
            line[len-1] = '\0';
            len--;
        }
        int ulen = utf8_strlen(line);
        if (ulen > max_w) max_w = ulen;
        table[r] = strdup(line);
    }
    for (int r = 0; r < char_height; r++) {
        int ulen = utf8_strlen(table[r]);
        if (ulen < max_w) {
            int need = max_w - ulen;
            int blen = strlen(table[r]);
            char *new_row = (char*)malloc(blen + need + 1);
            strcpy(new_row, table[r]);
            memset(new_row + blen, ' ', need);
            new_row[blen + need] = '\0';
            free(table[r]);
            table[r] = new_row;
        }
    }
    if (out_width) *out_width = max_w;
    return table;
}

static void load_font(const char *name) {
    FILE *f = open_font_file(name);
    if (!f) {
        fprintf(stderr, "%s: %s: Unable to open font file\n", progname, name);
        exit(1);
    }

    char *hdr = read_line(f);
    if (!hdr || (strncmp(hdr, "flf2", 4) != 0 && strncmp(hdr, "tlf2", 4) != 0)) {
        fprintf(stderr, "%s: %s: Not a FIGlet 2 font file\n", progname, name);
        exit(1);
    }

    hardblank = hdr[5];

    int commentlines = 0;
    int params_read = sscanf(hdr + 6, "%d %d %d %d %d %d %d %d",
                             &char_height, &baseline, &maxlen, &oldlayout,
                             &commentlines, &font_right2left, &full_layout, &codetag_count);

    if (params_read < 5) {
        fprintf(stderr, "%s: %s: Not a FIGlet 2 font file\n", progname, name);
        exit(1);
    }

    for (int i = 0; i < commentlines; i++) {
        read_line(f);
    }

    for (inchr ord = 32; ord <= 126; ord++) {
        int w = 0;
        char **tbl = read_figchar(f, &w);
        if (!tbl) break;
        add_char(ord, tbl, w);
    }

    inchr deutsch_ords[7] = {196, 214, 220, 228, 246, 252, 223};
    for (int i = 0; i < 7; i++) {
        int w = 0;
        char **tbl = read_figchar(f, &w);
        if (!tbl) break;
        add_char(deutsch_ords[i], tbl, w);
    }

    char *tagline;
    while ((tagline = read_line(f)) != NULL) {
        while (isspace(*tagline)) tagline++;
        if (*tagline == '\0') continue;
        inchr ord = parse_code(tagline);
        int w = 0;
        char **tbl = read_figchar(f, &w);
        if (!tbl) break;
        add_char(ord, tbl, w);
    }

    fclose(f);

    if (params_read >= 7 && full_layout > 0) {
        default_smush = full_layout;
    } else {
        if (oldlayout == -1) {
            default_smush = 0;
        } else if (oldlayout == 0) {
            default_smush = SM_KERN;
        } else {
            default_smush = SM_SMUSH;
            if (oldlayout & 1) default_smush |= SM_EQUAL;
            if (oldlayout & 2) default_smush |= SM_LOWLINE;
            if (oldlayout & 4) default_smush |= SM_HIERARCHY;
            if (oldlayout & 8) default_smush |= SM_PAIR;
            if (oldlayout & 16) default_smush |= SM_BIGX;
            if (oldlayout & 32) default_smush |= SM_HARDBLANK;
        }
    }
}

static void setup_active_smush() {
    if (smushmode_cmd == -100000) {
        active_smush = default_smush;
    } else if (smushmode_cmd == -2) {
        active_smush = default_smush;
    } else if (smushmode_cmd == -1) {
        active_smush = 0;
    } else if (smushmode_cmd == 0) {
        active_smush = SM_KERN;
    } else if (smushmode_cmd == SM_SMUSH) {
        active_smush = default_smush | SM_SMUSH;
    } else {
        if ((smushmode_cmd & SM_SMUSH) || (smushmode_cmd & SM_KERN)) {
            active_smush = smushmode_cmd;
        } else {
            active_smush = SM_SMUSH | smushmode_cmd;
        }
    }
}

static char smush_chars(char a, char b) {
    if (a == ' ') return b;
    if (b == ' ') return a;

    if (!(active_smush & SM_SMUSH)) return '\0';

    if ((active_smush & 63) == 0) {
        if (b == hardblank) return a;
        return b;
    }

    if ((active_smush & SM_EQUAL) && a == b) {
        if (a != hardblank || (active_smush & SM_HARDBLANK)) return a;
    }

    if (active_smush & SM_LOWLINE) {
        if (a == '_' && strchr("|/\\[]{}()<>", b)) return b;
        if (b == '_' && strchr("|/\\[]{}()<>", a)) return a;
    }

    if (active_smush & SM_HIERARCHY) {
        int rank_a = 0, rank_b = 0;
        if (a == '|') rank_a = 1;
        else if (a == '/' || a == '\\') rank_a = 2;
        else if (a == '[' || a == ']') rank_a = 3;
        else if (a == '{' || a == '}') rank_a = 4;
        else if (a == '(' || a == ')') rank_a = 5;
        else if (a == '<' || a == '>') rank_a = 6;

        if (b == '|') rank_b = 1;
        else if (b == '/' || b == '\\') rank_b = 2;
        else if (b == '[' || b == ']') rank_b = 3;
        else if (b == '{' || b == '}') rank_b = 4;
        else if (b == '(' || b == ')') rank_b = 5;
        else if (b == '<' || b == '>') rank_b = 6;

        if (rank_a > 0 && rank_b > 0) {
            if (rank_a > rank_b) return a;
            if (rank_b > rank_a) return b;
        }
    }

    if (active_smush & SM_PAIR) {
        if ((a == '[' && b == ']') || (a == ']' && b == '[')) return '|';
        if ((a == '{' && b == '}') || (a == '}' && b == '{')) return '|';
        if ((a == '(' && b == ')') || (a == ')' && b == '(')) return '|';
    }

    if (active_smush & SM_BIGX) {
        if (a == '/' && b == '\\') return '|';
        if (a == '\\' && b == '/') return 'Y';
        if (a == '>' && b == '<') return 'X';
    }

    if ((active_smush & SM_HARDBLANK) && a == hardblank && b == hardblank) {
        return hardblank;
    }

    return '\0';
}

typedef struct {
    char **output;
    int width;
    int char_count;
    int last_was_space;
    int last_space_width;
} LineBuffer;

static LineBuffer* create_line_buffer() {
    LineBuffer *buf = (LineBuffer*)calloc(1, sizeof(LineBuffer));
    buf->output = (char**)malloc(sizeof(char*) * char_height);
    for (int r = 0; r < char_height; r++) {
        buf->output[r] = (char*)calloc(1, 1024);
    }
    buf->width = 0;
    buf->last_was_space = 0;
    buf->last_space_width = 0;
    return buf;
}

static void free_line_buffer(LineBuffer *buf) {
    if (!buf) return;
    for (int r = 0; r < char_height; r++) free(buf->output[r]);
    free(buf->output);
    free(buf);
}

static int calc_overlap_ltr(LineBuffer *line, char **B_table, int B_width, inchr B_ord) {
    if (outwidth == 1) return 0;
    if (B_ord == ' ') return 0;

    if (line->width == 0) {
        if (active_smush == 0) return 0;
        int min_leading = 100000;
        for (int r = 0; r < char_height; r++) {
            int leading = 0;
            for (int i = 0; i < B_width; i++) {
                if (B_table[r][i] == ' ') leading++;
                else break;
            }
            if (leading < min_leading) min_leading = leading;
        }
        if (min_leading == 100000) min_leading = 0;
        return min_leading;
    }

    if (line->last_was_space) {
        int min_leading = 100000;
        for (int r = 0; r < char_height; r++) {
            int leading = 0;
            for (int i = 0; i < B_width; i++) {
                if (B_table[r][i] == ' ') leading++;
                else break;
            }
            if (leading < min_leading) min_leading = leading;
        }
        if (min_leading == 100000) min_leading = 0;
        return min_leading;
    }

    if (active_smush == 0) return 0;

    int min_kern = 100000;
    for (int r = 0; r < char_height; r++) {
        char *rowA = line->output[r];
        int lenA = utf8_strlen(rowA);
        char *rowB = B_table[r];

        int trailingA = 0;
        for (int i = lenA - 1; i >= 0; i--) {
            if (rowA[i] == ' ') trailingA++;
            else break;
        }

        int leadingB = 0;
        for (int i = 0; i < B_width; i++) {
            if (rowB[i] == ' ') leadingB++;
            else break;
        }

        int kern_row = trailingA + leadingB;
        if (kern_row < min_kern) min_kern = kern_row;
    }

    if (min_kern == 100000) min_kern = 0;

    if (!(active_smush & SM_SMUSH)) {
        return min_kern;
    }

    int smush_ok = 1;
    for (int r = 0; r < char_height; r++) {
        char *rowA = line->output[r];
        int lenA = utf8_strlen(rowA);
        char *rowB = B_table[r];

        int trailingA = 0;
        for (int i = lenA - 1; i >= 0; i--) {
            if (rowA[i] == ' ') trailingA++;
            else break;
        }

        int leadingB = 0;
        for (int i = 0; i < B_width; i++) {
            if (rowB[i] == ' ') leadingB++;
            else break;
        }

        if (trailingA + leadingB == min_kern) {
            int posA = lenA - 1 - trailingA;
            int posB = leadingB;
            char charA = (posA >= 0) ? rowA[posA] : ' ';
            char charB = (posB < B_width) ? rowB[posB] : ' ';

            if (charA != ' ' && charB != ' ') {
                if (smush_chars(charA, charB) == '\0') {
                    smush_ok = 0;
                    break;
                }
            }
        }
    }

    if (smush_ok) {
        return min_kern + 1;
    }
    return min_kern;
}

static int calc_overlap_rtl(LineBuffer *line, char **B_table, int B_width, inchr B_ord) {
    if (outwidth == 1) return 0;
    if (B_ord == ' ') return 0;

    if (line->width == 0 || line->last_was_space) {
        if (active_smush == 0) return 0;
        int min_trailing = 100000;
        for (int r = 0; r < char_height; r++) {
            int trailing = 0;
            for (int i = B_width - 1; i >= 0; i--) {
                if (B_table[r][i] == ' ') trailing++;
                else break;
            }
            if (trailing < min_trailing) min_trailing = trailing;
        }
        if (min_trailing == 100000) min_trailing = 0;
        return min_trailing;
    }

    if (active_smush == 0) return 0;

    int min_kern = 100000;
    for (int r = 0; r < char_height; r++) {
        char *rowA = line->output[r];
        int lenA = utf8_strlen(rowA);
        char *rowB = B_table[r];

        int leadingA = 0;
        for (int i = 0; i < lenA; i++) {
            if (rowA[i] == ' ') leadingA++;
            else break;
        }

        int trailingB = 0;
        for (int i = B_width - 1; i >= 0; i--) {
            if (rowB[i] == ' ') trailingB++;
            else break;
        }

        int kern_row = leadingA + trailingB;
        if (kern_row < min_kern) min_kern = kern_row;
    }

    if (min_kern == 100000) min_kern = 0;

    if (!(active_smush & SM_SMUSH)) {
        return min_kern;
    }

    int smush_ok = 1;
    for (int r = 0; r < char_height; r++) {
        char *rowA = line->output[r];
        int lenA = utf8_strlen(rowA);
        char *rowB = B_table[r];

        int leadingA = 0;
        for (int i = 0; i < lenA; i++) {
            if (rowA[i] == ' ') leadingA++;
            else break;
        }

        int trailingB = 0;
        for (int i = B_width - 1; i >= 0; i--) {
            if (rowB[i] == ' ') trailingB++;
            else break;
        }

        if (leadingA + trailingB == min_kern) {
            int posA = leadingA;
            int posB = B_width - 1 - trailingB;
            char charA = (posA < lenA) ? rowA[posA] : ' ';
            char charB = (posB >= 0) ? rowB[posB] : ' ';

            if (charA != ' ' && charB != ' ') {
                if (smush_chars(charB, charA) == '\0') {
                    smush_ok = 0;
                    break;
                }
            }
        }
    }

    if (smush_ok) {
        return min_kern + 1;
    }
    return min_kern;
}

static void append_char_to_line(LineBuffer *line, char **B_table, int B_width, int shift, inchr B_ord) {
    if (right2left) {
        if (line->width == 0) {
            int new_width = B_width - shift;
            if (new_width < 0) new_width = 0;
            for (int r = 0; r < char_height; r++) {
                free(line->output[r]);
                int alloc_size = new_width * 4 + 1024;
                line->output[r] = (char*)malloc(alloc_size);
                int blen = strlen(B_table[r]);
                memcpy(line->output[r], B_table[r], blen);
                line->output[r][blen] = '\0';
            }
            line->width = new_width;
            line->char_count = 1;
            line->last_was_space = (B_ord == ' ');
            if (B_ord == ' ') line->last_space_width = B_width;
            return;
        }

        int old_width = line->width;
        int new_width = old_width + B_width - shift;
        if (new_width < old_width) new_width = old_width;

        for (int r = 0; r < char_height; r++) {
            char *rowA = line->output[r];
            int lenA = strlen(rowA);
            char *rowB = B_table[r];

            int alloc_size = new_width * 4 + 1024;
            char *new_row = (char*)malloc(alloc_size);
            memset(new_row, ' ', new_width);
            new_row[new_width] = '\0';

            int offset = B_width - shift;
            memcpy(new_row + offset, rowA, lenA);

            int blen = strlen(rowB);
            for (int i = 0; i < blen; i++) {
                char b_ch = rowB[i];
                int pos = i;
                if (pos < new_width) {
                    char a_ch = new_row[pos];
                    if (a_ch == ' ') {
                        new_row[pos] = b_ch;
                    } else if (b_ch != ' ') {
                        char sm = smush_chars(b_ch, a_ch);
                        new_row[pos] = (sm != '\0') ? sm : b_ch;
                    }
                }
            }

            free(line->output[r]);
            line->output[r] = new_row;
        }
        line->width = new_width;
        line->char_count++;
        line->last_was_space = (B_ord == ' ');
        if (B_ord == ' ') line->last_space_width = B_width;
        return;
    }

    if (line->width == 0) {
        int new_width = B_width - shift;
        if (new_width < 0) new_width = 0;
        for (int r = 0; r < char_height; r++) {
            free(line->output[r]);
            int alloc_size = new_width * 4 + 1024;
            line->output[r] = (char*)malloc(alloc_size);
            int blen = strlen(B_table[r]);
            int start_byte = utf8_byte_offset(B_table[r], shift);
            int copy_len = blen - start_byte;
            if (copy_len < 0) copy_len = 0;
            memcpy(line->output[r], B_table[r] + start_byte, copy_len);
            line->output[r][copy_len] = '\0';
        }
        line->width = new_width;
        line->char_count = 1;
        line->last_was_space = (B_ord == ' ');
        if (B_ord == ' ') line->last_space_width = B_width;
        return;
    }

    int old_width = line->width;
    int new_width = old_width + B_width - shift;
    if (new_width < old_width) new_width = old_width;

    for (int r = 0; r < char_height; r++) {
        char *rowA = line->output[r];
        int lenA = strlen(rowA);
        char *rowB = B_table[r];

        int alloc_size = new_width * 4 + 1024;
        char *new_row = (char*)malloc(alloc_size);
        memset(new_row, ' ', new_width);
        new_row[new_width] = '\0';

        memcpy(new_row, rowA, lenA);

        int offset = old_width - shift;
        int blen = strlen(rowB);
        int byte_off = utf8_byte_offset(new_row, offset);

        for (int i = 0; i < blen; i++) {
            int pos = byte_off + i;
            if (pos < alloc_size - 1) {
                char b_ch = rowB[i];
                if (pos < lenA) {
                    char a_ch = new_row[pos];
                    if (a_ch == ' ') {
                        new_row[pos] = b_ch;
                    } else if (b_ch != ' ') {
                        char sm = smush_chars(a_ch, b_ch);
                        new_row[pos] = (sm != '\0') ? sm : b_ch;
                    }
                } else {
                    new_row[pos] = b_ch;
                }
            }
        }

        free(line->output[r]);
        line->output[r] = new_row;
    }

    line->width = new_width;
    line->char_count++;
    line->last_was_space = (B_ord == ' ');
    if (B_ord == ' ') line->last_space_width = B_width;
}

static void print_line(LineBuffer *line) {
    if (line->width == 0) return;

    int eff_just = justification;
    if (eff_just == -1) {
        eff_just = right2left ? 1 : 0;
    }

    int pad = 0;
    if (eff_just == 1) { // Right
        pad = outwidth - 1 - line->width;
        if (pad < 0) pad = 0;
    } else if (eff_just == 2) { // Center
        pad = (outwidth - line->width) / 2;
        if (pad < 0) pad = 0;
    }

    for (int r = 0; r < char_height; r++) {
        char *row = line->output[r];
        int len = strlen(row);

        for (int k = 0; k < pad; k++) putchar(' ');
        for (int k = 0; k < len; k++) {
            char c = row[k];
            putchar(c == hardblank ? ' ' : c);
        }
        putchar('\n');
    }
}

static inchr decode_utf8(const unsigned char **p) {
    unsigned char c = **p;
    if (c < 0x80) {
        (*p)++;
        return c;
    }
    if ((c & 0xE0) == 0xC0) {
        inchr res = (c & 0x1F) << 6;
        (*p)++;
        if (**p) res |= (**p & 0x3F), (*p)++;
        return res;
    }
    if ((c & 0xF0) == 0xE0) {
        inchr res = (c & 0x0F) << 12;
        (*p)++;
        if (**p) res |= (**p & 0x3F), (*p)++;
        if (**p) res |= (**p & 0x3F), (*p)++;
        return res;
    }
    if ((c & 0xF8) == 0xF0) {
        inchr res = (c & 0x07) << 18;
        (*p)++;
        if (**p) res |= (**p & 0x3F), (*p)++;
        if (**p) res |= (**p & 0x3F), (*p)++;
        if (**p) res |= (**p & 0x3F), (*p)++;
        return res;
    }
    (*p)++;
    return c;
}

typedef struct {
    CharNode *node;
    inchr code;
    int is_space;
} QueuedChar;

static void process_text(const char *text) {
    int is_utf8 = 0;
    ControlFile *cf = control_files;
    while (cf) {
        if (cf->utf8_mode) is_utf8 = 1;
        cf = cf->next;
    }

    QueuedChar q[8192];
    int q_len = 0;

    const unsigned char *p = (const unsigned char*)text;
    while (*p) {
        inchr c;
        if (is_utf8) {
            c = decode_utf8(&p);
        } else {
            c = *p;
            p++;
        }

        if (c == '\r') continue;
        if (c == '\n') {
            q[q_len].node = NULL;
            q[q_len].code = '\n';
            q[q_len].is_space = 0;
            q_len++;
            continue;
        }

        inchr mapped_c = map_char(c);
        CharNode *node = get_char_node(mapped_c);
        if (!node) node = get_char_node(' ');
        if (!node) continue;

        q[q_len].node = node;
        q[q_len].code = mapped_c;
        q[q_len].is_space = (c == ' ');
        q_len++;
    }

    int idx = 0;
    while (idx < q_len) {
        if (q[idx].code == '\n') {
            if (idx == 0 || q[idx - 1].code == '\n') {
                for (int r = 0; r < char_height; r++) putchar('\n');
            }
            idx++;
            continue;
        }

        LineBuffer *line = create_line_buffer();
        int last_space_q_idx = -1;

        int start_idx = idx;
        int i = start_idx;
        while (i < q_len && q[i].code != '\n') {
            CharNode *node = q[i].node;
            int shift = right2left ? calc_overlap_rtl(line, node->table, node->width, node->ord)
                                   : calc_overlap_ltr(line, node->table, node->width, node->ord);

            if (outwidth > 1 && line->width > 0 && (line->width + node->width - shift) > outwidth) {
                if (last_space_q_idx != -1 && last_space_q_idx > start_idx) {
                    free_line_buffer(line);
                    line = create_line_buffer();
                    for (int k = start_idx; k < last_space_q_idx; k++) {
                        CharNode *knode = q[k].node;
                        int kshift = right2left ? calc_overlap_rtl(line, knode->table, knode->width, knode->ord)
                                                : calc_overlap_ltr(line, knode->table, knode->width, knode->ord);
                        append_char_to_line(line, knode->table, knode->width, kshift, knode->ord);
                    }
                    print_line(line);
                    free_line_buffer(line);
                    line = NULL;
                    idx = last_space_q_idx + 1;
                    break;
                } else {
                    print_line(line);
                    free_line_buffer(line);
                    line = NULL;
                    idx = i;
                    break;
                }
            }

            if (outwidth == 1 && line->width > 0) {
                print_line(line);
                free_line_buffer(line);
                line = NULL;
                idx = i;
                break;
            }

            append_char_to_line(line, node->table, node->width, shift, node->ord);
            if (q[i].is_space) {
                last_space_q_idx = i;
            }
            i++;
        }

        if (line) {
            print_line(line);
            free_line_buffer(line);
            idx = i;
        }
    }
}

int main(int argc, char **argv) {
    progname = get_basename(argv[0]);

    int opt;
    while ((opt = getopt(argc, argv, "I:m:w:f:d:C:cklnoprstvxDELNRSWXAF")) != -1) {
        switch (opt) {
            case 'c': justification = 2; break;
            case 'l': justification = 0; break;
            case 'r': justification = 1; break;
            case 'x': justification = -1; break;
            case 'k': smushmode_cmd = SM_KERN; break;
            case 'W': smushmode_cmd = -1; break;
            case 'o': smushmode_cmd = SM_SMUSH | SM_PAIR; break;
            case 's': smushmode_cmd = SM_SMUSH; break;
            case 'S': smushmode_cmd = SM_SMUSH; break;
            case 'n': paragraphmode = 0; break;
            case 'p': paragraphmode = 1; break;
            case 't': use_terminal_width = 1; break;
            case 'w': outwidth = atoi(optarg); if (outwidth <= 0) outwidth = 80; break;
            case 'd': fontdir = optarg; break;
            case 'f': fontname = optarg; break;
            case 'C': load_control_file(optarg); break;
            case 'N': control_files = NULL; last_cf_ptr = &control_files; break;
            case 'm': smushmode_cmd = atoi(optarg); break;
            case 'I': infocode = atoi(optarg); break;
            case 'v': print_version(); return 0;
            case 'D': deutschmode = 1; break;
            case 'E': deutschmode = 0; break;
            case 'X': deutschmode = 0; break;
            case 'L': right2left = 0; break;
            case 'R': right2left = 1; break;
            case 'A': break;
            case 'F':
                fprintf(stderr, "%s: illegal option -- F\n", progname);
                print_usage(stderr);
                fprintf(stderr, "\nBecause of numerous incompatibilities, the \"-F\" option has been\n");
                fprintf(stderr, "removed.  It has been replaced by the \"figlist\" program, which is now\n");
                fprintf(stderr, "included in the basic FIGlet package.  \"figlist\" is also available\n");
                fprintf(stderr, "from  http://www.figlet.org/under UNIX utilities.\n");
                return 1;
            default:
                print_usage(stderr);
                return 1;
        }
    }

    if (use_terminal_width) {
        struct winsize ws;
        if (ioctl(STDOUT_FILENO, TIOCGWINSZ, &ws) == 0 && ws.ws_col > 0) {
            outwidth = ws.ws_col;
        } else if (ioctl(STDERR_FILENO, TIOCGWINSZ, &ws) == 0 && ws.ws_col > 0) {
            outwidth = ws.ws_col;
        } else if (ioctl(STDIN_FILENO, TIOCGWINSZ, &ws) == 0 && ws.ws_col > 0) {
            outwidth = ws.ws_col;
        }
    }

    if (infocode >= 0) {
        switch (infocode) {
            case 0:
                print_version();
                return 0;
            case 1:
                printf("20205\n");
                return 0;
            case 2:
                printf("%s\n", fontdir ? fontdir : (getenv("FIGLET_FONTDIR") ? getenv("FIGLET_FONTDIR") : DEFAULTFONTDIR));
                return 0;
            case 3:
                printf("%s\n", fontname ? fontname : DEFAULTFONTFILE);
                return 0;
            case 4:
                printf("%d\n", outwidth);
                return 0;
            case 5:
                printf("flf2 tlf2\n");
                return 0;
            default:
                return 0;
        }
    }

    load_font(fontname ? fontname : DEFAULTFONTFILE);
    setup_active_smush();

    if (optind < argc) {
        size_t total_len = 0;
        for (int i = optind; i < argc; i++) {
            total_len += strlen(argv[i]) + 1;
        }
        char *buf = (char*)malloc(total_len + 1);
        buf[0] = '\0';
        for (int i = optind; i < argc; i++) {
            strcat(buf, argv[i]);
            if (i < argc - 1) strcat(buf, " ");
        }
        process_text(buf);
        free(buf);
    } else {
        char line_buf[8192];
        if (paragraphmode) {
            char *para_buf = (char*)malloc(65536);
            para_buf[0] = '\0';
            size_t para_len = 0;

            while (fgets(line_buf, sizeof(line_buf), stdin)) {
                size_t l = strlen(line_buf);
                while (l > 0 && (line_buf[l-1] == '\r' || line_buf[l-1] == '\n')) {
                    line_buf[l-1] = '\0';
