                printf("%s\n", fontname ? fontname : DEFAULTFONTFILE);
                return 0;
            case 4:
                printf("%d\n", outwidth);
                return 0;
            case 5:
                printf("flf2 tlf2\n");
                return 0;
            default:
                return 0;
        }
    }

    load_font(fontname ? fontname : DEFAULTFONTFILE);
    setup_active_smush();

    if (optind < argc) {
        size_t total_len = 0;
        for (int i = optind; i < argc; i++) {
            total_len += strlen(argv[i]) + 1;
        }
        char *buf = (char*)malloc(total_len + 1);
        buf[0] = '\0';
        for (int i = optind; i < argc; i++) {
            strcat(buf, argv[i]);
            if (i < argc - 1) strcat(buf, " ");
        }
        process_text(buf);
        free(buf);
    } else {
        char line_buf[8192];
        if (paragraphmode) {
            char *para_buf = (char*)malloc(65536);
            para_buf[0] = '\0';
            size_t para_len = 0;

            while (fgets(line_buf, sizeof(line_buf), stdin)) {
                size_t l = strlen(line_buf);
                while (l > 0 && (line_buf[l-1] == '\r' || line_buf[l-1] == '\n')) {
                    line_buf[l-1] = '\0';
                    l--;
                }

                char *tp = line_buf;
                while (isspace(*tp)) tp++;
                if (*tp == '\0') {
                    if (para_len > 0) {
                        strcat(para_buf, " ");
                        process_text(para_buf);
                        process_text("\n");
                        para_buf[0] = '\0';
                        para_len = 0;
                    } else {
                        process_text("\n");
                    }
                } else {
                    if (para_len > 0) {
                        strcat(para_buf, " ");
                        para_len++;
                    }
                    strcat(para_buf, tp);
                    para_len += strlen(tp);
                }
            }
            if (para_len > 0) {
                strcat(para_buf, " ");
                process_text(para_buf);
            }
            free(para_buf);
        } else {
            while (fgets(line_buf, sizeof(line_buf), stdin)) {
                size_t l = strlen(line_buf);
                if (l > 0 && line_buf[l-1] == '\n') {
                    process_text(line_buf);
                } else {
                    char tmp[8193];
                    snprintf(tmp, sizeof(tmp), "%s\n", line_buf);
                    process_text(tmp);
                }
            }
        }
    }

    return 0;
}
